public class PrimitiveTypesDemo {
    public static void main(String[] args) {
        byte age = 25;               // 1 byte: -128 to 127
        int population = 8_000_000;  // 4 bytes: the default integer
        long distance = 93_000_000L; // 8 bytes: L suffix required
        double pi = 3.14159;         // 8 bytes: default for decimals
        char grade = 'A';            // 2 bytes: a single Unicode char
        boolean isActive = true;     // true/false only
        System.out.println(distance + " miles, grade " + grade);
    }
}
